import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


triplet_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor triplet_margin_loss(torch::Tensor anchor,
                                  torch::Tensor positive,
                                  torch::Tensor negative,
                                  double margin);
"""

triplet_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void triplet_margin_loss_kernel(const T* __restrict__ A,
                                           const T* __restrict__ P,
                                           const T* __restrict__ N,
                                           T* __restrict__ Out,
                                           int batch,
                                           int dim,
                                           float margin,
                                           float inv_batch)
{
  constexpr int Threads = 256;
  constexpr float Eps = 1.0e-6f;

  const int row = blockIdx.x;
  if (row >= batch) return;

  Tensor mA = make_tensor(make_gmem_ptr(A),
                          make_shape(batch, dim),
                          make_stride(dim, Int<1>{}));
  Tensor mP = make_tensor(make_gmem_ptr(P),
                          make_shape(batch, dim),
                          make_stride(dim, Int<1>{}));
  Tensor mN = make_tensor(make_gmem_ptr(N),
                          make_shape(batch, dim),
                          make_stride(dim, Int<1>{}));

  __shared__ float s_pos[Threads];
  __shared__ float s_neg[Threads];

  const int tid = threadIdx.x;
  float pos_acc = 0.0f;
  float neg_acc = 0.0f;
  if ((dim & 3) == 0) {
    const float4* __restrict__ A4 =
        reinterpret_cast<const float4*>(A + static_cast<long long>(row) * dim);
    const float4* __restrict__ P4 =
        reinterpret_cast<const float4*>(P + static_cast<long long>(row) * dim);
    const float4* __restrict__ N4 =
        reinterpret_cast<const float4*>(N + static_cast<long long>(row) * dim);
    const int dim4 = dim >> 2;
    for (int i = tid; i < dim4; i += Threads) {
      const float4 a = A4[i];
      const float4 p = P4[i];
      const float4 n = N4[i];
      const float dp0 = a.x - p.x;
      const float dp1 = a.y - p.y;
      const float dp2 = a.z - p.z;
      const float dp3 = a.w - p.w;
      const float dn0 = a.x - n.x;
      const float dn1 = a.y - n.y;
      const float dn2 = a.z - n.z;
      const float dn3 = a.w - n.w;
      pos_acc += dp0 * dp0 + dp1 * dp1 + dp2 * dp2 + dp3 * dp3;
      neg_acc += dn0 * dn0 + dn1 * dn1 + dn2 * dn2 + dn3 * dn3;
    }
  } else {
    for (int i = tid; i < dim; i += Threads) {
      const float a = static_cast<float>(mA(row, i));
      const float p = static_cast<float>(mP(row, i));
      const float n = static_cast<float>(mN(row, i));
      const float d_pos = a - p;
      const float d_neg = a - n;
      pos_acc += d_pos * d_pos;
      neg_acc += d_neg * d_neg;
    }
  }

  s_pos[tid] = pos_acc;
  s_neg[tid] = neg_acc;
  __syncthreads();

  for (int stride = Threads / 2; stride > 0; stride >>= 1) {
    if (tid < stride) {
      s_pos[tid] += s_pos[tid + stride];
      s_neg[tid] += s_neg[tid + stride];
    }
    __syncthreads();
  }

  if (tid == 0) {
    float dist_pos = sqrtf(fmaxf(s_pos[0], 0.0f));
    float dist_neg = sqrtf(fmaxf(s_neg[0], 0.0f));
    dist_pos = fmaxf(dist_pos, Eps);
    dist_neg = fmaxf(dist_neg, Eps);

    const float loss = fmaxf(dist_pos - dist_neg + margin, 0.0f);
    atomicAdd(Out, loss * inv_batch);
  }
}

torch::Tensor triplet_margin_loss(torch::Tensor anchor,
                                  torch::Tensor positive,
                                  torch::Tensor negative,
                                  double margin)
{
  TORCH_CHECK(anchor.is_cuda() && positive.is_cuda() && negative.is_cuda(),
              "anchor, positive and negative must be CUDA tensors");
  TORCH_CHECK(anchor.scalar_type() == at::kFloat &&
              positive.scalar_type() == at::kFloat &&
              negative.scalar_type() == at::kFloat,
              "Only float32 is supported");
  TORCH_CHECK(anchor.sizes() == positive.sizes() && anchor.sizes() == negative.sizes(),
              "anchor, positive and negative must have identical shapes");
  TORCH_CHECK(anchor.dim() >= 1, "inputs must have at least one dimension");

  auto A = anchor.contiguous();
  auto P = positive.contiguous();
  auto N = negative.contiguous();

  const int64_t batch64 = A.size(0);
  const int64_t numel64 = A.numel();
  TORCH_CHECK(batch64 > 0, "batch dimension must be non-empty");
  TORCH_CHECK(numel64 % batch64 == 0, "invalid flattened feature dimension");

  const int64_t dim64 = numel64 / batch64;
  TORCH_CHECK(batch64 <= INT_MAX && dim64 <= INT_MAX,
              "tensor is too large for this kernel");

  const int batch = static_cast<int>(batch64);
  const int dim = static_cast<int>(dim64);
  const float inv_batch = 1.0f / static_cast<float>(batch);

  auto out = torch::empty({}, A.options());
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  cudaMemsetAsync(out.data_ptr<float>(), 0, sizeof(float), stream);

  dim3 grid(batch);
  dim3 block(256);

  triplet_margin_loss_kernel<float><<<grid, block, 0, stream>>>(
      A.data_ptr<float>(),
      P.data_ptr<float>(),
      N.data_ptr<float>(),
      out.data_ptr<float>(),
      batch,
      dim,
      static_cast<float>(margin),
      inv_batch);

  const auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess,
              "triplet_margin_loss_kernel launch failed: ",
              cudaGetErrorString(err));

  return out;
}
"""

triplet_ext = load_inline(
    name="cute_triplet_margin_loss_ext",
    cpp_sources=triplet_cpp_decl,
    cuda_sources=triplet_cuda_src,
    functions=["triplet_margin_loss"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, margin=1.0):
        super().__init__()
        self.margin = float(margin)
        self._ext = triplet_ext

    def forward(self, anchor, positive, negative):
        return self._ext.triplet_margin_loss(
            anchor, positive, negative, self.margin
        )

